		return idle >= (cfg.StuckSeconds or 18)
	end

	local function isInteractLike(typ)
		if type(typ) ~= "string" or typ == "" then
			return false
		end
		if string.sub(typ, 1, 11) == "Investigate" then
			return true
		end
		return typ == "Unlock"
			or typ == "Loot"
			or typ == "Open"
			or typ == "Interact"
			or typ == "Free"
			or typ == "Wake"
			or typ == "Check On"
			or typ == "Escort"
			or typ == "Deliver Object"
			or typ == "Deliver"
			or typ == "Talk"
			or typ == "Automatic Talk"
			or typ == "GiveItemTo"
			or typ == "Plant"
			or typ == "Harvest"
			or typ == "Water"
			or typ == "Rescue"
			or typ == "CollectLocalItem"
			or typ == "CollectLocal"
	end

	local function scopedInvalidate(qs)
		if not GB.Cache then
			return
		end
		if not GB.Cache.invalidatePrefix then
			GB.Cache.invalidate()
			return
		end
		local o = qs and qs.Objective
		local typ = o and o.Type
		if typ == "Kill" or typ == "Defeat" or typ == "Hit" or typ == "Destroy" or typ == "Shoot" then
			GB.Cache.invalidatePrefix("res:enemy:")
			if typ == "Destroy" then
				GB.Cache.invalidatePrefix("res:object:")
				GB.Cache.invalidatePrefix("res:marker:")
			end
			return
		end
		if typ == "Talk" or typ == "Automatic Talk" or typ == "GiveItemTo" or typ == "Deliver" then
