		return beginInvest(stat, math.min(1, n), "quest")
	end

	function M.status()
		if M._remoteVerified then
			return "RUNTIME_VERIFIED", nil
		end
		if M._blocked then
			return "BLOCKED", M._blockedReason
		end
		if M._attempted then
