		local gold = GB.State.get().Gold or 0
		if gold < 50 then
			GB.Log.log("TRAVEL", "Rowboat needs 50G")
			return false
		end
		local part = GB.Resolver.shopItem("Rowboat")
		if part then
			GB.World.moveTo(part, 12)
		end
