		M.owner = "Tutorial"
		M.lastGate = gate
		if M.lastStep ~= key then
			M.lastStep = key
			M.continueAttempts = 0
			M.dumpedTree = nil
			GB.Log.log("GATE", string.format("detected ContinueOverlay %s payload=%s", tostring(gate.Id), tostring(gate.Payload)))
