			end
			GB.Log.warn("GATE", "BLOCKING_GATE_UNRESOLVED " .. key)
			GB.Log.warn(
				"GATE",
				string.format(
					"id=%s payload=%s method=%s before=Enabled after=still",
					tostring(gate.Id),
					tostring(gate.Payload),
					tostring(method)
				)
			)
			M.DumpTutorialState()
			if GB.DumpRuntimeIssue then
				GB.DumpRuntimeIssue()
			end
		end
		return false
	end

	function M.ExecuteGate(gate)
		gate = gate or M.GetCurrentGate()
		if not gate then
			M.owner = nil
			return false
		end
