		if age <= 0 then
			return 0
		end
		return (M._intentSwitches or 0) * (60 / math.max(age, 1))
	end

	local function setOwner(owner, target)
		owner = owner or "IDLE"
		local key = tostring(owner) .. "|" .. tostring(target or "-")
