		end)()
		if type(factory) ~= "function" then
			error("UI/ManualController.lua did not return a factory")
		end
		return factory(GB)
	end)
	if not ok then
		error("[Kaitun UI] init UI/ManualController.lua: " .. tostring(inst), 0)
	end
	GB["UIController"] = inst
	UI.Controller = inst
end

