		end)()
		if type(factory) ~= "function" then
			error("UI/RuntimeExtensions.lua did not return a factory")
		end
		return factory(GB)
	end)
	if not ok then
		error("[Kaitun UI] init UI/RuntimeExtensions.lua: " .. tostring(inst), 0)
	end
	GB["UIExtensions"] = inst
	UI.Extensions = inst
end

